import csv
import io
import re


def parse_csv(raw_csv: str):
    reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"', strict=False)
    records = [row for row in reader if row and any(value.strip() for value in row)]

    if not records:
        return {"columns": [], "rows": []}

    def header_score(row):
        normalized = [re.sub(r"[^a-z0-9]+", " ", value.lower()).strip() for value in row]
        score = 0
        if normalized and ("country" in normalized[0] or "region" in normalized[0]):
            score += 1
        if len(normalized) > 1 and any(word in normalized[1].split() for word in ("year", "vintage", "date")):
            score += 1
        if len(normalized) > 2 and any(word in normalized[2].split() for word in ("product", "name", "item")):
            score += 1
        if len(normalized) > 3 and any(word in normalized[3].split() for word in ("consumption", "quantity", "amount", "sales")):
            score += 1
        return score

    header_index = next(
        (index for index, row in enumerate(records) if len(row) == 4 and header_score(row) >= 2),
        None,
    )
    if header_index is None:
        header_index = next(
            (index for index, row in enumerate(records) if len(row) == 4),
            0,
        )

    columns = records[header_index]
    width = len(columns)
    if width == 0:
        return {"columns": [], "rows": []}

    rows = []
    for record in records[header_index + 1:]:
        if len(record) < width:
            record = record + [""] * (width - len(record))
        elif len(record) > width:
            record = record[:width - 1] + [",".join(record[width - 1:])]
        rows.append(record)

    return {"columns": columns, "rows": rows}
